import 'package:flutter/material.dart';import '../data/app_store.dart';import '../models/equipment_knowledge.dart';import '../theme/operon_theme.dart';
class EquipmentKnowledgeScreen extends StatefulWidget{final AppStore store;final String tag;const EquipmentKnowledgeScreen({super.key,required this.store,required this.tag});@override State<EquipmentKnowledgeScreen> createState()=>_S();}
class _S extends State<EquipmentKnowledgeScreen>{late EquipmentKnowledge k;late final TextEditingController range,notes,valve,circuit,related,procedures,source;
@override void initState(){super.initState();k=widget.store.knowledgeFor(widget.tag);range=TextEditingController(text:k.normalRange);notes=TextEditingController(text:k.operatorNotes);valve=TextEditingController(text:k.valvePosition);circuit=TextEditingController(text:k.processCircuit);related=TextEditingController(text:k.relatedTags.join(', '));procedures=TextEditingController(text:k.procedureRefs.join('\n'));source=TextEditingController(text:k.source);}
@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:Text('${widget.tag} Knowledge')),body:ListView(padding:const EdgeInsets.all(16),children:[const Card(child:ListTile(leading:Icon(Icons.verified_user,color:OperonTheme.teal),title:Text('Controlled operational knowledge'),subtitle:Text('Enter only site-approved or source-backed information. OPERON does not invent operating limits, valve positions or procedure requirements.'))),_f(range,'Normal operating range','e.g. approved normal range + units'),_f(valve,'Valve / position guidance','Recorded normal position or operating band'),_f(circuit,'Process circuit','Where this equipment sits in the process'),_f(related,'Related equipment TAGs','Comma separated'),_f(procedures,'Approved procedure / document references','One reference per line',lines:4),_f(notes,'Operator knowledge / notes','Practical source-backed information',lines:5),_f(source,'Source / owner','Procedure, manual, approved note, responsible role'),const SizedBox(height:14),FilledButton.icon(onPressed:_save,icon:const Icon(Icons.save),label:const Text('Save operational knowledge'))]));
Widget _f(TextEditingController x,String label,String hint,{int lines=2})=>Padding(padding:const EdgeInsets.only(top:12),child:TextField(controller:x,maxLines:lines,decoration:InputDecoration(labelText:label,hintText:hint)));
void _save(){k.normalRange=range.text.trim();k.valvePosition=valve.text.trim();k.processCircuit=circuit.text.trim();k.relatedTags=related.text.split(',').map((e)=>e.trim().toUpperCase()).where((e)=>e.isNotEmpty).toList();k.procedureRefs=procedures.text.split('\n').map((e)=>e.trim()).where((e)=>e.isNotEmpty).toList();k.operatorNotes=notes.text.trim();k.source=source.text.trim();widget.store.saveKnowledge(k);Navigator.pop(context);}
}
